import AVFoundation
import AudioToolbox
import CoreMedia
import Foundation
import XCTest
@testable import TTMediaKit

/// Default (always-on) verification of the Dolby production chain against the hermetic corpus.
///
/// These tests replace the retired personal-film corpus (`REF-V4`/`REF-V5`/`REF-V6`), whose
/// hard-coded `~/Downloads` paths made the default Swift media gate unrunnable on any machine
/// that did not own the original films. The corpus they use is committed to the repository and
/// is regenerated by a script that never reads personal media.
///
/// Three production-chain semantics stay covered for all three Dolby track classes
/// (AC-3 6ch, E-AC-3 6ch, AC-3 5ch):
/// 1. track identity and audio sample parameters published by the Rust demuxer,
/// 2. real Dolby packets reaching the Swift pipeline,
/// 3. no wrong track, correct error isolation and correct presentation state.
final class HermeticDolbyCorpusTests: XCTestCase {

    // MARK: - 1. Track identity and audio sample parameters

    func testHermeticDolbyCorpusPublishesTrackIdentityAndSampleParameters() async throws {
        for sample in HermeticDolbyCorpusFixtures.samples {
            let url = HermeticDolbyCorpusFixtures.url(for: sample)
            guard requireFixture(url, sample: sample) else { continue }

            let transport = MediaWorkerDirectTransport()
            let opened = try await transport.openMedia(path: url.path, targetTracks: nil)
            let info = TTMediaStreamInfo(sessionId: opened.sessionId, dictionary: opened.metadata)
            try await transport.closeMedia(sessionId: opened.sessionId)

            XCTAssertEqual(
                info.metadataCapability, "v1_structured_contract_v1",
                "\(sample.id) must publish the V1 structured contract"
            )
            XCTAssertEqual(
                info.selectedVideoTrackNumber, sample.expectedVideoTrackNumber,
                "\(sample.id) selected video track number"
            )
            XCTAssertEqual(
                info.selectedAudioTrackNumber, sample.expectedAudioTrackNumber,
                "\(sample.id) selected audio track number"
            )
            XCTAssertEqual(
                info.primaryAudioTrackNumber, sample.expectedAudioTrackNumber,
                "\(sample.id) primary audio track number"
            )
            XCTAssertEqual(
                info.audioTracks.count, 1,
                "\(sample.id) must publish exactly one active audio track"
            )
            XCTAssertEqual(
                info.catalogAudioTracks.count, sample.expectedCatalogAudioTrackCount,
                "\(sample.id) must publish every container audio track in the catalog"
            )

            let audio = try XCTUnwrap(info.audioTracks.first, "\(sample.id) must publish the selected audio track")
            XCTAssertEqual(audio.trackIndex, sample.expectedAudioTrackNumber, "\(sample.id) audio trackIndex")
            XCTAssertEqual(audio.codec, sample.expectedCodec, "\(sample.id) canonical codec")
            XCTAssertEqual(audio.codecName, sample.expectedCodec.rawValue, "\(sample.id) codec name")
            XCTAssertEqual(audio.rawCodecId, sample.expectedRawCodecID, "\(sample.id) raw CodecID")
            XCTAssertEqual(audio.channels, sample.expectedChannels, "\(sample.id) channel count")
            XCTAssertEqual(audio.sampleRate, sample.expectedSampleRate, "\(sample.id) sample rate")
            XCTAssertEqual(audio.channelLayout, sample.expectedChannelLayout, "\(sample.id) channel layout")
            XCTAssertEqual(audio.audioProfile, sample.expectedAudioProfile, "\(sample.id) audio profile")
            XCTAssertEqual(
                audio.channelsSource, "probed_bitstream_channels",
                "\(sample.id) channel count must come from the Dolby bitstream, not from the container"
            )
            XCTAssertEqual(
                audio.sampleRateSource, "probed_bitstream_sample_rate",
                "\(sample.id) sample rate must come from the Dolby bitstream, not from the container"
            )
            XCTAssertTrue(audio.demuxSelectable, "\(sample.id) selected track must be demux selectable")
            XCTAssertTrue(audio.isSelectedForPackets, "\(sample.id) selected track must carry packets")
            XCTAssertEqual(
                audio.codecPrivateFormat, "none",
                "\(sample.id) reproduces the production condition of a Dolby track without CodecPrivate"
            )
            XCTAssertNil(
                audio.codecPrivateSha256,
                "\(sample.id) must not publish a CodecPrivate digest for a track without CodecPrivate"
            )

            try assertDecoyTrackIsNotSelected(info: info, sample: sample)
        }
    }

    /// Asserts that the non-playable decoy audio track is present but never selected.
    ///
    /// This is the hermetic stand-in for the retired corpus' real-film situation: the
    /// container carries a `default`-flagged audio track the demuxer cannot select, and the
    /// Dolby track must still be the one that carries packets.
    private func assertDecoyTrackIsNotSelected(
        info: TTMediaStreamInfo,
        sample: HermeticDolbyCorpusFixtures.Sample
    ) throws {
        guard let decoyNumber = sample.expectedDecoyTrackNumber else {
            XCTAssertEqual(
                sample.expectedCatalogAudioTrackCount, 1,
                "\(sample.id) has no decoy track and must publish a single audio track"
            )
            return
        }
        let decoy = try XCTUnwrap(
            info.catalogAudioTracks.first(where: { $0.trackIndex == decoyNumber }),
            "\(sample.id) must publish the decoy audio track #\(decoyNumber) in its catalog"
        )
        XCTAssertEqual(decoy.rawCodecId, sample.expectedDecoyRawCodecID, "\(sample.id) decoy raw CodecID")
        XCTAssertEqual(decoy.channels, sample.expectedDecoyChannels, "\(sample.id) decoy channel count")
        XCTAssertFalse(decoy.demuxSelectable, "\(sample.id) the decoy track must not be demux selectable")
        XCTAssertFalse(decoy.isSelectedForPackets, "\(sample.id) the decoy track must not carry packets")
        XCTAssertEqual(decoy.selectionStatus, "catalog_only", "\(sample.id) decoy track selection status")
        XCTAssertNotEqual(
            info.selectedAudioTrackNumber, decoyNumber,
            "\(sample.id) the demuxer must not select the non-playable decoy track"
        )
        XCTAssertEqual(
            info.catalogAudioTracks.filter(\.isSelectedForPackets).count, 1,
            "\(sample.id) exactly one audio track may carry packets"
        )
    }

    // MARK: - 2. Real packets reaching the Swift pipeline

    @MainActor
    func testHermeticDolbyCorpusFeedsRealPacketsIntoTheSwiftPipeline() async throws {
        for sample in HermeticDolbyCorpusFixtures.samples {
            let url = HermeticDolbyCorpusFixtures.url(for: sample)
            guard requireFixture(url, sample: sample) else { continue }

            let firstAudioPacket = try await Self.readFirstAudioPacket(at: url)
            let payload = try XCTUnwrap(
                firstAudioPacket?.payloadData,
                "\(sample.id) the demuxer must deliver a first audio packet"
            )
            XCTAssertEqual(
                Array(payload.prefix(HermeticDolbyCorpusFixtures.syncWord.count)),
                HermeticDolbyCorpusFixtures.syncWord,
                "\(sample.id) the first audio packet must start with the ATSC A/52 sync word 0B77"
            )
            XCTAssertEqual(
                firstAudioPacket?.duration.seconds ?? 0,
                HermeticDolbyCorpusFixtures.expectedFrameDurationSeconds,
                accuracy: 0.002,
                "\(sample.id) an audio packet must be exactly one 32 ms Dolby frame"
            )

            // Layer 2 — build a format and sample buffer from the fixture's expected
            // parameters and a real demuxed frame. This does not verify the controller's
            // parameter mapping or successful decoding/consumption by the renderer.
            try assertPipelineAcceptsRealDolbyFrame(sample: sample, packet: firstAudioPacket)

            // Layer 3 — the playback controller must keep presenting while the Dolby track is
            // the active one, and its isolation decision must follow the decoder capability.
            let controller = AVSampleBufferWorkerPlaybackController(
                url: url,
                client: MediaWorkerXPCClient(transport: MediaWorkerDirectTransport())
            )
            await controller.startPlayback(autoPlay: true)
            try await Task.sleep(nanoseconds: 250_000_000)

            XCTAssertNil(controller.fatalError, "\(sample.id) must not suffer a fatal playback error")
            XCTAssertTrue(controller.isPlaying, "\(sample.id) must stay in active playback")
            XCTAssertGreaterThan(controller.enqueuedVideoPacketCount, 0, "\(sample.id) must enqueue video frames")
            XCTAssertEqual(
                controller.ignoredMismatchedStreamPackets, 0,
                "\(sample.id) must not drop packets as stream-mismatched"
            )
            XCTAssertGreaterThan(
                CMTimeGetSeconds(controller.coordinator.synchronizer.currentTime()), 0.0,
                "\(sample.id) the synchronizer clock must advance"
            )
            assertAudioDeliveryAndIsolation(controller: controller, sample: sample)

            await controller.stop()
        }
    }

    // MARK: - 3. Negative evidence: the assertions above must have discriminating power

    func testHermeticDolbyCorpusRejectsUnavailableWrongCodecAndWrongTrack() async throws {
        // (a) An unavailable file source must fail loudly instead of yielding an empty stream.
        let missingURL = HermeticDolbyCorpusFixtures.testsRoot()
            .appendingPathComponent("Fixtures/hermetic-swift/not-a-real-sample.mkv")
        let missingTransport = MediaWorkerDirectTransport()
        do {
            _ = try await missingTransport.openMedia(path: missingURL.path, targetTracks: nil)
            XCTFail("Opening a missing corpus file must fail instead of reporting an empty stream")
        } catch {
            // Expected: an unavailable source is an error, never a silent success.
        }

        // (b) A corrupt package must fail to open instead of degrading into a partial pass.
        let sample = HermeticDolbyCorpusFixtures.samples[0]
        let url = HermeticDolbyCorpusFixtures.url(for: sample)
        guard requireFixture(url, sample: sample) else { return }
        let corruptURL = FileManager.default.temporaryDirectory
            .appendingPathComponent("ttmedia_mm47_corrupt_\(UUID().uuidString).mkv")
        let truncated = try Data(contentsOf: url).prefix(1024)
        try Data(truncated).write(to: corruptURL)
        defer { try? FileManager.default.removeItem(at: corruptURL) }
        let corruptTransport = MediaWorkerDirectTransport()
        do {
            _ = try await corruptTransport.openMedia(path: corruptURL.path, targetTracks: nil)
            XCTFail("A truncated corpus package must fail to open instead of passing silently")
        } catch {
            // Expected: a corrupt package is an error, never a silent success.
        }

        // (c) The three samples must be distinguishable, so a wrong codec or a wrong channel
        //     count in the demuxer cannot satisfy the identity assertions.
        let infos = try await Self.streamInfos(for: HermeticDolbyCorpusFixtures.samples)
        XCTAssertEqual(
            infos.count, HermeticDolbyCorpusFixtures.samples.count,
            "every corpus sample must be openable for the discrimination checks"
        )
        guard infos.count == HermeticDolbyCorpusFixtures.samples.count else { return }
        let ac3Six = try XCTUnwrap(infos[0].audioTracks.first, "AC-3 6ch sample audio track")
        let eac3Six = try XCTUnwrap(infos[1].audioTracks.first, "E-AC-3 6ch sample audio track")
        let ac3Five = try XCTUnwrap(infos[2].audioTracks.first, "AC-3 5ch sample audio track")
        XCTAssertEqual(ac3Six.codec, .ac3, "AC-3 6ch sample codec")
        XCTAssertEqual(eac3Six.codec, .eac3, "E-AC-3 6ch sample codec")
        XCTAssertEqual(ac3Five.codec, .ac3, "AC-3 5ch sample codec")
        XCTAssertNotEqual(ac3Six.rawCodecId, eac3Six.rawCodecId)
        XCTAssertNotEqual(ac3Six.channels, ac3Five.channels)
        XCTAssertEqual(ac3Six.channels, 6)
        XCTAssertEqual(ac3Five.channels, 5)
    }

    func testOnlyTracksTheSystemDecoderCannotDecodeAreIsolatedAsUnsupported() {
        // A genuinely undecodable codec MUST be rejected by the track-selection stage.
        let vorbis = TTMediaAudioTrackInfo(
            trackIndex: 2, codec: .vorbis, codecName: "vorbis",
            sampleRate: 48_000, channels: 2, demuxSelectable: true
        )
        let vorbisFault = AVSampleBufferAudioPipeline.validateCandidateTrack(vorbis)
        XCTAssertEqual(
            vorbisFault?.kind, .unsupportedAudioTrack,
            "a codec the system decoder cannot decode must be reported as an unsupported track"
        )
        XCTAssertEqual(
            vorbisFault?.stage, .trackSelection,
            "the rejection must happen at the track-selection stage"
        )

        // The Dolby codecs MUST NOT be rejected by the same stage.
        for codec in [AudioCodec.ac3, .eac3] {
            let dolby = TTMediaAudioTrackInfo(
                trackIndex: 3, codec: codec, codecName: codec.rawValue,
                sampleRate: 48_000, channels: 6, demuxSelectable: true
            )
            XCTAssertNil(
                AVSampleBufferAudioPipeline.validateCandidateTrack(dolby),
                "\(codec.rawValue) is decodable by the system decoder and must not be rejected"
            )
        }
    }

    func testHermeticAudioDeliveryRejectsConstructionFaultAfterEnqueue() {
        // A previously accepted packet cannot excuse a later construction or stall fault.
        for stage in [AVSampleBufferAudioFaultStage.formatDescription, .sampleBufferEnqueue, .pipelineStall] {
            let fault = AVSampleBufferAudioFault(
                kind: .audioInitializationFailed, stage: stage,
                codecName: "ac3", diagnosticDetail: "Regression counterexample",
                sampleRateHz: 48_000, channelCount: 6
            )
            for rendererFailed in [false, true] {
                XCTAssertFalse(Self.acceptsAudioDelivery(
                    enqueuedPacketCount: 1, rendererFailed: rendererFailed, fault: fault
                ), "A real \(stage) fault must not be hidden by an earlier enqueued packet")
            }
        }
        let rendererFault = AVSampleBufferAudioFault(
            kind: .audioInitializationFailed, stage: .rendererFailure,
            codecName: "ac3", diagnosticDetail: "Renderer failure control",
            sampleRateHz: 48_000, channelCount: 6
        )
        XCTAssertFalse(Self.acceptsAudioDelivery(enqueuedPacketCount: 1, rendererFailed: false, fault: rendererFault))
        XCTAssertTrue(Self.acceptsAudioDelivery(enqueuedPacketCount: 0, rendererFailed: true, fault: rendererFault))
        // Renderer failure can be observed before the asynchronous fault is committed.
        XCTAssertTrue(Self.acceptsAudioDelivery(enqueuedPacketCount: 0, rendererFailed: true, fault: nil))
        XCTAssertTrue(Self.acceptsAudioDelivery(enqueuedPacketCount: 1, rendererFailed: false, fault: nil))
        XCTAssertFalse(Self.acceptsAudioDelivery(enqueuedPacketCount: 0, rendererFailed: false, fault: nil))
    }

    // MARK: - Helpers

    /// Fails the test when a required corpus sample is missing.
    ///
    /// A missing fixture is a hard failure: the default gate must never degrade into a
    /// silently reduced verification.
    private func requireFixture(_ url: URL, sample: HermeticDolbyCorpusFixtures.Sample) -> Bool {
        let exists = FileManager.default.fileExists(atPath: url.path)
        XCTAssertTrue(
            exists,
            """
            \(sample.id) corpus sample is missing at \(url.path). \
            Regenerate it with: \(HermeticDolbyCorpusFixtures.regenerationCommand)
            """
        )
        return exists
    }

    /// The only tolerated fault is a renderer-stage failure backed by the real renderer.
    /// A failed renderer may precede its asynchronous fault; no audible output is required.
    private static func acceptsAudioDelivery(
        enqueuedPacketCount: Int,
        rendererFailed: Bool,
        fault: AVSampleBufferAudioFault?
    ) -> Bool {
        if let fault {
            guard fault.kind == .audioInitializationFailed, fault.stage == .rendererFailure else {
                return false
            }
            return rendererFailed
        }
        return enqueuedPacketCount > 0 || rendererFailed
    }

    /// Checks delivery and fault evidence together, so queued packets cannot hide a later fault.
    @MainActor
    private func assertAudioDeliveryAndIsolation(
        controller: AVSampleBufferWorkerPlaybackController,
        sample: HermeticDolbyCorpusFixtures.Sample
    ) {
        let renderer = controller.audioPipeline.audioRenderer
        let rendererFailed = renderer.status == .failed || renderer.error != nil
        XCTAssertTrue(
            Self.acceptsAudioDelivery(
                enqueuedPacketCount: controller.enqueuedAudioPacketCount,
                rendererFailed: rendererFailed,
                fault: controller.audioFault
            ),
            "\(sample.id) must enqueue Dolby packets without a construction/stall fault; "
                + "only a real renderer-stage failure is tolerated"
        )
        guard let fault = controller.audioFault else { return }
        XCTAssertEqual(
            fault.codecName, sample.expectedCodec.rawValue,
            "\(sample.id) the fault must name the Dolby track, never another audio track"
        )
        XCTAssertEqual(
            fault.channelCount, sample.expectedChannels,
            "\(sample.id) the fault must carry the real channel count"
        )
        XCTAssertEqual(
            fault.sampleRateHz, sample.expectedSampleRate,
            "\(sample.id) the fault must carry the real sample rate"
        )
    }

    /// Feeds a real demuxed Dolby frame into the Swift audio pipeline.
    ///
    /// Uses fixture expectations to create a format description, wraps a real demuxed frame
    /// in a CoreMedia sample buffer, and calls the production enqueue API without an attached
    /// synchronizer. This checks construction; it does not prove the controller's actual
    /// parameter mapping, decoder consumption, or audible output.
    private func assertPipelineAcceptsRealDolbyFrame(
        sample: HermeticDolbyCorpusFixtures.Sample,
        packet: MediaPacketDTO?
    ) throws {
        let unwrapped = try XCTUnwrap(packet, "\(sample.id) must provide a Dolby frame")
        let pipeline = AVSampleBufferAudioPipeline()
        let parameters = AudioFormatParameters(
            codec: sample.expectedCodec,
            sampleRate: sample.expectedSampleRate,
            channelCount: UInt32(sample.expectedChannels),
            bitsPerChannel: 16,
            channelLayoutTag: 0
        )
        let description = try pipeline.createAudioFormatDescription(from: parameters)
        let asbd = try XCTUnwrap(
            CMAudioFormatDescriptionGetStreamBasicDescription(description),
            "\(sample.id) must produce an audio format description"
        )
        XCTAssertEqual(asbd.pointee.mSampleRate, sample.expectedSampleRate, "\(sample.id) decoder sample rate")
        XCTAssertEqual(
            Int(asbd.pointee.mChannelsPerFrame), sample.expectedChannels,
            "\(sample.id) decoder channel count"
        )
        XCTAssertEqual(
            asbd.pointee.mFormatID,
            sample.expectedCodec == .ac3 ? kAudioFormatAC3 : kAudioFormatEnhancedAC3,
            "\(sample.id) decoder format id"
        )
        XCTAssertEqual(
            asbd.pointee.mFramesPerPacket, 1536,
            "\(sample.id) decoder frame size must be one 1536-sample Dolby frame"
        )
        XCTAssertNoThrow(
            try pipeline.reconstructAndEnqueue(packet: unwrapped, formatDescription: description),
            "\(sample.id) the Swift pipeline must accept the real Dolby frame"
        )
    }

    /// Reads the first audio packet the real demuxer produces for a corpus sample.
    private static func readFirstAudioPacket(at url: URL) async throws -> MediaPacketDTO? {
        let transport = MediaWorkerDirectTransport()
        let opened = try await transport.openMedia(path: url.path, targetTracks: nil)
        defer { Task { try? await transport.closeMedia(sessionId: opened.sessionId) } }
        for _ in 0..<16 {
            guard let raw = try await transport.readNextPacket(sessionId: opened.sessionId) else {
                return nil
            }
            let packet = try JSONDecoder().decode(MediaPacketDTO.self, from: raw)
            if packet.mediaType == .audio {
                return packet
            }
        }
        return nil
    }

    /// Opens every corpus sample and returns its published stream information.
    private static func streamInfos(
        for samples: [HermeticDolbyCorpusFixtures.Sample]
    ) async throws -> [TTMediaStreamInfo] {
        var infos: [TTMediaStreamInfo] = []
        for sample in samples {
            let url = HermeticDolbyCorpusFixtures.url(for: sample)
            guard FileManager.default.fileExists(atPath: url.path) else { continue }
            let transport = MediaWorkerDirectTransport()
            let opened = try await transport.openMedia(path: url.path, targetTracks: nil)
            infos.append(TTMediaStreamInfo(sessionId: opened.sessionId, dictionary: opened.metadata))
            try await transport.closeMedia(sessionId: opened.sessionId)
        }
        return infos
    }
}
